template.query:
mutation BulkImportTodos($todos: [TodoImportInput!]!) {
  bulkCreateNodes(
    tableId: "58"
    nodes: $todos
  ) {
    success
    createdCount
    totalCount
    errors {
      message
      line
    }
    nodes {
      id
      content
      attributes {
        name
        value
      }
    }
  }
}
